// Utility để tự động setup proxy endpoint trong Next.js app
// File này sẽ được copy vào project của user khi họ setup
import { load } from 'cheerio';
/**
 * Auto-setup proxy endpoint cho embed-react
 * Copy file này vào /pages/api/embed.ts trong Next.js project
 */
export default async function handler(req, res) {
    if (req.method !== 'GET') {
        return res.status(405).json({ error: 'Method not allowed' });
    }
    const { url } = req.query;
    if (!url || typeof url !== 'string') {
        return res.status(400).json({ error: 'URL parameter is required' });
    }
    try {
        const response = await fetch(url, {
            headers: {
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
            },
            redirect: 'follow',
        });
        if (!response.ok) {
            return res.status(response.status).json({ error: 'Failed to fetch URL' });
        }
        let html = await response.text();
        let $ = load(html);
        // Đảm bảo body tồn tại
        if ($('body').length === 0) {
            $('html').append('<body></body>');
        }
        // Inject resize script
        const resizeScript = `
      <script>
        (function() {
          'use strict';
          
          if (window.__iframeResizeHandler) {
            return;
          }
          
          let lastHeight = 0;
          let isUpdating = false;
          let updateTimer = null;
          const TOLERANCE = 10;
          const MAX_HEIGHT = 10000;
          
          function getActualHeight() {
            const body = document.body;
            const html = document.documentElement;
            
            if (!body || !html) {
              return 0;
            }
            
            const height = Math.max(
              body.scrollHeight || 0,
              body.offsetHeight || 0,
              body.clientHeight || 0,
              html.scrollHeight || 0,
              html.offsetHeight || 0,
              html.clientHeight || 0
            );
            
            return Math.ceil(Math.min(height, MAX_HEIGHT));
          }
          
          function sendHeight(height) {
            if (height <= 0 || height > MAX_HEIGHT) {
              return;
            }
            
            const heightDiff = Math.abs(height - lastHeight);
            
            if (!isUpdating && heightDiff > TOLERANCE) {
              lastHeight = height;
              isUpdating = true;
              
              if (window.parent && window.parent !== window) {
                window.parent.postMessage({ 
                  type: 'iframe-resize', 
                  height: height 
                }, '*');
              }
              
              setTimeout(function() {
                isUpdating = false;
              }, 200);
            }
          }
          
          function updateHeight() {
            if (updateTimer) {
              clearTimeout(updateTimer);
            }
            
            updateTimer = setTimeout(function() {
              requestAnimationFrame(function() {
                const height = getActualHeight();
                sendHeight(height);
              });
            }, 200);
          }
          
          // Initial load
          if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', function() {
              setTimeout(updateHeight, 300);
              setTimeout(updateHeight, 800);
              setTimeout(updateHeight, 1500);
            });
          } else {
            setTimeout(updateHeight, 300);
            setTimeout(updateHeight, 800);
            setTimeout(updateHeight, 1500);
          }
          
          // Window load
          window.addEventListener('load', function() {
            setTimeout(updateHeight, 500);
            setTimeout(updateHeight, 1500);
            setTimeout(updateHeight, 3000);
          }, { once: true });
          
          // Window resize
          let resizeTimer = null;
          window.addEventListener('resize', function() {
            if (resizeTimer) {
              clearTimeout(resizeTimer);
            }
            resizeTimer = setTimeout(updateHeight, 500);
          });
          
          // Listen for trigger message
          window.addEventListener('message', function(event) {
            if (event.data && event.data.type === 'trigger-resize') {
              updateHeight();
            }
          });
          
          // MutationObserver
          if (window.MutationObserver) {
            const observer = new MutationObserver(function() {
              updateHeight();
            });
            
            if (document.body) {
              observer.observe(document.body, {
                childList: true,
                subtree: true,
                attributes: false,
                characterData: false
              });
              
              setTimeout(function() {
                if (observer) {
                  observer.disconnect();
                }
              }, 30000);
            }
          }
          
          // Image load listeners
          function setupImageListeners() {
            const images = document.querySelectorAll('img');
            images.forEach(function(img) {
              if (!img.complete) {
                img.addEventListener('load', updateHeight, { once: true });
                img.addEventListener('error', updateHeight, { once: true });
              }
            });
          }
          
          if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', setupImageListeners);
          } else {
            setupImageListeners();
          }
          
          // Check for iframes inside
          function setupIframeListeners() {
            const iframes = document.querySelectorAll('iframe');
            iframes.forEach(function(iframe) {
              try {
                iframe.addEventListener('load', updateHeight, { once: true });
              } catch (e) {
                // Ignore cross-origin errors
              }
            });
          }
          
          if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', setupIframeListeners);
          } else {
            setupIframeListeners();
          }
          
          window.__iframeResizeHandler = true;
        })();
      </script>
    `;
        // Inject script vào cuối body
        const body = $('body');
        if (body.length > 0) {
            body.append(resizeScript);
        }
        else {
            $('html').append(resizeScript);
        }
        // Set headers để cho phép CORS và trả về HTML
        res.setHeader('Content-Type', 'text/html; charset=utf-8');
        res.setHeader('Access-Control-Allow-Origin', '*');
        res.setHeader('Access-Control-Allow-Methods', 'GET');
        return res.status(200).send($.html());
    }
    catch (error) {
        console.error('Error fetching URL:', error);
        return res.status(500).json({ error: 'Internal server error' });
    }
}
